sparql:
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>

SELECT DISTINCT ?dataset ?title
WHERE {
  ?dataset a dcat:Dataset .
  ?dataset dct:title ?title .
  OPTIONAL { ?dataset dct:description ?desc }
  FILTER (
    CONTAINS(LCASE(STR(?title)), "agriculture") ||
    CONTAINS(LCASE(STR(?desc)), "agriculture")
  )
}
LIMIT 10

PREFIX dcat: <http://www.w3.org/ns/dcat#>

SELECT (COUNT(?dataset) AS ?totalFinanceDatasets)
WHERE {
  ?dataset a dcat:Dataset .
  ?dataset dcat:theme <http://publications.europa.eu/resource/authority/data-theme/ECON> .
}

PREFIX dcat: <http://www.w3.org/ns/dcat#>

SELECT (COUNT(?dataset) AS ?totalTransportDatasets)
WHERE {
  ?dataset a dcat:Dataset .
  ?dataset dcat:theme <http://publications.europa.eu/resource/authority/data-theme/TRAN> .
}

PREFIX dcat: <http://www.w3.org/ns/dcat#>

SELECT (COUNT(?dataset) AS ?totalGovDatasets)
WHERE {
  ?dataset a dcat:Dataset .
  ?dataset dcat:theme <http://publications.europa.eu/resource/authority/data-theme/GOVE> .
}

PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>

SELECT DISTINCT ?dataset ?title
WHERE {
  {
    ?dataset a dcat:Dataset .
    ?dataset dct:title ?title .
    ?dataset dcat:theme <http://publications.europa.eu/resource/authority/data-theme/EDUC> .
    FILTER(LANG(?title) = "en")
  }
  UNION
  {
    ?dataset a dcat:Dataset .
    ?dataset dct:title ?title .
    ?dataset dcat:theme <http://publications.europa.eu/resource/authority/data-theme/HEAL> .
    FILTER(LANG(?title) = "en")
  }
}
LIMIT 20
